  const saved=()=>{try{return JSON.parse(stationPicker.dataset.values||'[]')}catch{return[]}};
  const update=()=>{const codes=saved();if(stationNode)stationNode.value=codes[0]||'';if(regionNode)regionNode.value=codes.map(code=>masterRegionForStation(code)||'Belum dipetakan').join(' / ');trigger.textContent=codes.length?codes.slice(0,3).join(', ')+(codes.length>3?' +'+(codes.length-3):''):'Pilih Station';};
